// Rotate Array - Rotate the array to the right by k steps
var array = AnimatedArray<Int>()
for val in 1...5 {
    array.append(val)
}
let k = 2

func rotateArray(arr: inout AnimatedArray<Int>, steps: Int) {
    guard !arr.isEmpty else { return }
    let actualSteps = steps % arr.count
    for _ in 0..<actualSteps {
        if let lastVal = arr.remove(at: arr.count - 1) {
            arr.insert(lastVal, at: 0)
        }
    }
}

rotateArray(arr: &array, steps: k)
